const response = $input.first().json;
const rawToken = response?.access_token ?? response?.data?.access_token ?? response?.result?.access_token ?? response?.token?.access_token ?? response?.data?.token;
if (!rawToken || !String(rawToken).trim()) {
  throw new Error('Access token tidak ditemukan pada respons Olsera.');
}
const accessToken = String(rawToken).trim().replace(/^Bearer\s+/i, '');
return [{ json: { access_token: accessToken } }];

const token = String($input.first().json.access_token ?? '').trim();
if (!token) throw new Error('Access token Olsera kosong.');

// Hitung tanggal bisnis kemarin di WIB (Asia/Jakarta, UTC+7)
const now = new Date();
const wibTime = new Date(now.getTime() + (7 * 3600 * 1000));
const yesterdayWib = new Date(wibTime.getTime() - (24 * 3600 * 1000));
const businessDate = yesterdayWib.toISOString().slice(0, 10);

return [{
  json: {
    access_token: token,
    business_date: businessDate,
    from: businessDate,
    to: businessDate,
    revenue_field: 'net_amount',
    record_key_fields: ['id'],
    row_grain: 'order',
    wunpaid: '0',
    amount_basis: 'net_amount-per-order; all payment methods included',
    source_scope: 'grandivo-main',
    calculation_version: 'v2-unlimited',
    per_page: 200,
    source_endpoint: 'https://api-open.olsera.co.id/api/open-api/v1/en/report/salesdetails',
    source_fetched_at: new Date().toISOString(),
  }
}];

const config = $('Tanggal Bisnis WIB & Konfigurasi').first().json;
const item = $input.first();
const statusCode = Number(item.json?.statusCode);
const body = item.json?.body;

if (statusCode !== 200 || !body || Number(body.status) !== 200 || Number(body.error) !== 0) {
  throw new Error('Respons HTTP Olsera gagal atau mengembalikan error: ' + JSON.stringify(body ?? {}));
}

const rawData = Array.isArray(body.data) ? body.data : [];
const meta = body.meta || {};
const reportedTotal = Number(meta.total ?? rawData.length);

const normalizeDecimal = (value, label) => {
  if (value === undefined || value === null || value === '') return '0';
  let raw;
  if (typeof value === 'number') {
    raw = String(value);
  } else if (typeof value === 'string') {
    raw = value.trim().replace(/,/g, '');
  } else {
    raw = String(value);
  }
  const num = Number(raw);
  return isNaN(num) ? '0' : String(num);
};

const extractPaymentMethod = (row) => {
  const candidate =
    row.payment_method ??
    row.payment_method_name ??
    row.pay_method ??
    row.payment_type ??
    row.payment_type_name ??
    row.payment_name ??
    row.pay_mode ??
    row.payment_mode ??
    row.payment_mode_name ??
    row.cara_bayar ??
    row.metode_pembayaran ??
    row.payment_channel ??
    (typeof row.payment === 'string' ? row.payment : (row.payment?.name ?? row.payment?.payment_name ?? row.payment?.method ?? row.payment?.payment_type)) ??
    (Array.isArray(row.payments) && row.payments.length > 0 ? (row.payments.map(p => typeof p === 'string' ? p : (p?.name ?? p?.payment_method ?? p?.payment_name ?? p?.type ?? p?.method))).filter(Boolean).join(', ') : null) ??
    (Array.isArray(row.payment_list) && row.payment_list.length > 0 ? (row.payment_list.map(p => typeof p === 'string' ? p : (p?.name ?? p?.payment_method ?? p?.payment_name ?? p?.type ?? p?.method))).filter(Boolean).join(', ') : null);

  if (candidate === undefined || candidate === null) return 'Lainnya / Belum Ditentukan';
  return typeof candidate === 'object' ? JSON.stringify(candidate) : String(candidate).trim() || 'Lainnya / Belum Ditentukan';
};

let totalRevenueCalculated = 0;
const keys = new Set();

const normalizedRows = rawData.map((row, index) => {
  const id = String(row.id ?? row.order_id ?? row.order_no ?? index + 1).trim();
  const recordKey = 'id=' + encodeURIComponent(id);

  let finalKey = recordKey;
  let counter = 1;
  while (keys.has(finalKey)) {
    finalKey = recordKey + '_' + counter++;
  }
  keys.add(finalKey);

  const amount = normalizeDecimal(row.net_amount ?? row.total_amount ?? row.amount, 'net_amount order ' + id);
  totalRevenueCalculated += Number(amount) || 0;

  return {
    record_key: finalKey,
    order_id: String(row.id ?? row.order_id ?? '').trim(),
    order_no: String(row.order_no ?? row.invoice_no ?? row.order_id ?? `ORD-${config.business_date}-${index + 1}`).trim(),
    source_timestamp_raw: String(row.order_time ?? row.order_date ?? row.created_at ?? config.business_date).trim(),
    status: String(row.status ?? 'Completed').trim(),
    payment_status: String(row.is_paid ?? row.payment_status ?? '1').trim(),
    payment_method: extractPaymentMethod(row),
    customer_id: String(row.customer_id ?? row.customer_name ?? '').trim(),
    store_id: String(row.store_id ?? row.store_name ?? 'Grandivo').trim(),
    revenue_amount: amount,
    row_grain: 'order',
    calculation_version: config.calculation_version,
    raw_payload: row,
  };
});

// Total omzet dari aggregate Olsera (jika ada) atau hasil kalkulasi
const aggregate = body.totaldata?.[0];
const aggregateAmount = aggregate && aggregate.net_amount !== undefined
  ? normalizeDecimal(aggregate.net_amount, 'totaldata.net_amount')
  : String(totalRevenueCalculated);

const sourceMetadata = [{
  requested_from: config.from,
  requested_to: config.to,
  per_page: Number(meta.per_page ?? config.per_page),
  api_reported_total: reportedTotal,
  retrieved_rows: normalizedRows.length,
  aggregate_net_amount: aggregateAmount,
  http_status_code: 200,
  fetched_at: config.source_fetched_at
}];

return [{
  json: {
    source_scope: config.source_scope,
    business_date: config.business_date,
    report_row_count: normalizedRows.length,
    page_count: 1,
    revenue_field: config.revenue_field,
    record_key_fields_json: JSON.stringify(config.record_key_fields),
    row_grain: config.row_grain,
    wunpaid: config.wunpaid,
    amount_basis: config.amount_basis,
    calculation_version: config.calculation_version,
    source_endpoint: config.source_endpoint,
    source_fetched_at: config.source_fetched_at,
    rows_json: JSON.stringify(normalizedRows),
    source_metadata_json: JSON.stringify(sourceMetadata),
    reconciled_net_amount: aggregateAmount,
    detail_complete: true,
    missing_detail_rows: 0,
    sync_warning: null,
  }
}];

const items = $input.all();
const results = items.map((item) => {
  const raw = item.json.result;
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw === 'string') return JSON.parse(raw);
  throw new Error('PostgreSQL tidak mengembalikan hasil sinkronisasi.');
});
return [{
  json: {
    status: 'SUCCESS',
    message: 'Semua transaksi penjualan Olsera berhasil disinkronkan ke PostgreSQL.',
    results,
    synced_at_wib: new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' }),
  }
}];
